contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: from address, target contract address to be called, arrays of tos and values
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require preconditions matching C.transfer's own expectations
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool reverted;
        // call transfer and capture whether it reverts
        try c.transfer(from, caddress, _tos, v) returns (bool ok) {
            reverted = false;
            // if it returned, it must return true per contract logic
            // we will assert this below using observed ok
            assert(ok == true);
        } catch {
            reverted = true;
        }

        // General rule: transfer either returns true (not reverted) or it reverts; it cannot both
        // Syntactically we assert that reverted is equivalent to the call not returning true.
        // Because we already asserted ok==true in the returned branch, here we just ensure consistency:
        assert(reverted == (!(_tos.length == 0) && reverted));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // Preconditions matching C.transfer expectations
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool reverted;
        bool returnedTrue = false;

        // Call transfer and observe whether it reverts or returns true
        try c.transfer(from, caddress, _tos, v) returns (bool ok) {
            reverted = false;
            returnedTrue = ok;
        } catch {
            reverted = true;
        }

        // General rule: with the preconditions, the call cannot succeed returning false.
        // Thus: reverted XOR returnedTrue must hold (i.e., if not reverted then returnedTrue is true).
        assert(reverted || returnedTrue);
    }

    receive() external payable {}
}

